-- Angola milestones. GENERATED by new_country_scaffold.py from
-- angola-spec.json, with ONE HAND EDIT described below.
--
-- THE SCAFFOLDER CANNOT CLASSIFY AN OFF-BOARD ROW and does not pretend
-- to: it derives obligation_status from on_tracker alone, 'live' on the
-- board and 'unreviewed' off it. That is right for a past-dated row and
-- wrong for a future-dated one, which 520's standing invariant refuses
-- outright -- correctly, because "we have not looked at this yet" is not
-- a statement anybody should be able to make about a date that has not
-- happened. Both off-board rows here are 'context' instead, and both are
-- context in 520's sense: they are true, they are dated, and neither is
-- an obligation a reader should act on.
--
--   ao-dp7125-vigor    the decree entering into force. The anchor.
--   ao-statutory-12m   Article 37's twelve-month clock running out on
--                      21 September 2026. Real, and NOT the operative
--                      date -- see the phase-two note below.
--
-- THE TWO DATES DISAGREE AND THE DISAGREEMENT IS THE FINDING. Article 37
-- gives twelve months from Executive Decree 683/25 (in force around
-- 21 September 2025), which catches every remaining taxpayer from
-- 21 September 2026. EY Angola reads it exactly that way. Three in-market
-- sources -- Cegid, a certified vendor; Expansão in January 2026; Líder
-- Magazine in April 2026 quoting the AGT's board president -- instead say
-- 1 January 2027. They are reconcilable: the first phase's statutory date
-- was 20 September 2025 and it commenced on 1 January 2026, so Angolan
-- practice has twice aligned commencement to the calendar year. The board
-- carries 1 January 2027 with an EXPECTED badge because it is the date a
-- reader should plan to and is not the date in the instrument; the
-- statutory expiry sits off-board so the deep-dive timeline still shows
-- it. If the AGT publishes an instruction naming either, this row and
-- that badge both want revisiting.
--
-- Sourcing: every source_url here was opened and read. The Ministry of
-- Finance's own announcement of the 1 January 2026 date exists at
-- minfin.gov.ao but returned no readable body to automated fetch, so the
-- phase-one row cites EY Angola's alert, which states the date and the
-- covered taxpayers, rather than a government page nobody here has read.
-- The decree text itself is cited from angolex.com; the Ministry's PDF at
-- ucm.minfin.gov.ao carries no extractable text layer.

-- Angola: milestones + English translations. Generated by
-- new_country_scaffold.py; INSERT OR IGNORE throughout (idempotent).

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ao-dp7125-vigor', id, '2025-09-20', 1, 'https://angolex.com/paginas/decreto-presidencial/regime-juridico-das-facturas-71a-25a.html', 0, '[]', NULL, 'b2b', 'context' FROM countries WHERE code = 'AO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ao-dp7125-vigor', 'en', 'Regime Jurídico das Facturas takes effect', 'Presidential Decree 71/25 of 20 March 2025 entered into force six months after publication, replacing the 2018 invoicing regime. Article 16 makes electronic invoicing obligatory for General and Simplified VAT regime taxpayers; Article 17(2) requires software validated or supplied by the AGT that transmits in real time and cannot delete an issued document.', '["Read Articles 16, 17 and 25 rather than a vendor summary", "Note that the obligation attaches to the VAT regime, not to turnover"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ao-b2b-phase1', id, '2026-01-01', 0, 'https://www.ey.com/pt_ao/technical/tax-alerts/facturacao-electronica-a-partir-de-1-de-janeiro-de-2026', 1, '[{"label": "Portal do Contribuinte — facturação electrónica", "url": "https://portaldocontribuinte.minfin.gov.ao/"}]', NULL, 'b2b', 'live' FROM countries WHERE code = 'AO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ao-b2b-phase1', 'en', 'Large taxpayers and State suppliers', 'Electronic issuance and real-time communication become mandatory for large taxpayers, suppliers to the State, and taxpayers issuing invoices of 25 million kwanzas or more. A transitional window from 1 October 2025 had allowed paper without penalty while the AGT certified software. By April 2026 the AGT reported 28,949 taxpayers on the system generating 250,000 to 500,000 invoices a day.', '["Confirm your billing software appears on the AGT''s certified list", "Register every establishment in the Portal do Contribuinte before requesting series", "Request an invoice series per establishment — series cannot be shared"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ao-statutory-12m', id, '2026-09-21', 0, 'https://angolex.com/paginas/decreto-presidencial/regime-juridico-das-facturas-71a-25a.html', 0, '[]', NULL, 'b2b', 'context' FROM countries WHERE code = 'AO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ao-statutory-12m', 'en', 'Article 37''s twelve-month transitional period expires', 'Article 37 restricts the obligation to large taxpayers and State suppliers for twelve months from the implementing Executive Decree 683/25, which took effect around 21 September 2025. On the decree''s own clock every remaining taxpayer is caught from this date. Angolan practice has instead aligned each phase to 1 January, and this entry is kept off the board because no authority has confirmed it as the operative date.', '["Watch for an AGT instruction naming the operative date for the second phase"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope, obligation_status) SELECT 'ao-b2b-phase2', id, '2027-01-01', 0, 'https://www.cegid.com/ao/o-que-e-a-facturacao-electronica/', 1, '[{"label": "Portal do Contribuinte — facturação electrónica", "url": "https://portaldocontribuinte.minfin.gov.ao/"}]', 'expected', 'b2b', 'live' FROM countries WHERE code = 'AO';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ao-b2b-phase2', 'en', 'All remaining VAT-registered taxpayers', 'The obligation extends to every remaining taxpayer in the General and Simplified VAT regimes. The date is reported consistently by in-market sources and by certified software vendors, and it follows the pattern set by the first phase, whose statutory date of 20 September 2025 also commenced on 1 January. It is not the date written in the decree, which is why it carries an expected badge.', '["Smaller taxpayers should not wait for the certified-software market to clear", "Check whether an AGT instruction has moved this date before planning to it"]');

